/* ENGINEER OS — local-first single-user learning dashboard */
const phases=[
 {name:'Foundation',start:'2026-12-07',end:'2027-01-10',desc:'Build a durable base in Python, Git, Linux, scientific computing and geospatial data.',milestone:'Comfortably write modular Python, manage Git repositories and process basic scientific and geospatial data.'},
 {name:'Backend Engineering',start:'2027-01-11',end:'2027-01-31',desc:'Turn fundamentals into reliable APIs, data models and secure backend applications.',milestone:'Independently build a basic backend with APIs, database integration, authentication and tests.'},
 {name:'AI Engineering',start:'2027-02-01',end:'2027-02-28',desc:'Build AI-powered applications with tools, retrieval, evaluation and reliable orchestration.',milestone:'Integrate LLMs, design tool-using agents, implement basic RAG and evaluate AI behaviour.'},
 {name:'Systems Engineering & Independence',start:'2027-03-01',end:'2027-04-04',desc:'Develop production engineering instincts and prove your skills through independent delivery.',milestone:'Independently build, explain, debug and deploy a backend application with an AI component.'}
];
const weekInfo=[
['Python & Developer Foundations','Python syntax, variables, conditions, loops, collections, functions, files, CSV, JSON, exceptions, Git and Linux.','A command-line Agricultural Observation Analyzer with a documented CSV schema. It rejects malformed rows with row numbers, reports valid/invalid counts and per-field summary statistics, and writes a deterministic JSON report. Include sample input, usage instructions, and a Git repository with meaningful commits.'],
['Python Beyond the Basics','OOP, classes, modules, type hints, iterators, generators, logging, pytest and reusable packages.','A reusable installable Python package with separate parsing, validation, analysis and reporting modules. Provide typed public functions, structured logging, a generator for streaming rows, pytest coverage for normal and invalid inputs, and a README with setup and usage examples.'],
['Scientific Computing','NumPy, Pandas, Matplotlib, SciPy fundamentals and OpenCV fundamentals.','A reproducible notebook or script that loads a real or clearly labelled sample dataset, cleans missing values, computes descriptive statistics and one SciPy analysis, then exports at least two labelled plots. Add a short interpretation of results and record dataset provenance.'],
['Geospatial Foundations','Raster and vector data, GeoTIFF, coordinate reference systems, Rasterio, GDAL and satellite imagery preprocessing.','A geospatial preprocessing script that inspects a GeoTIFF, reports its CRS, bounds, resolution and NoData value, reprojects it to a chosen CRS, clips it to a vector boundary and exports a validated GeoTIFF plus a processing summary. Include a small sample or reproducible data instructions.'],
['Scientific Pipeline Engineering','Reusable processing functions, validation, pipeline stages, reproducibility, configuration and profiling.','A configurable, end-to-end scientific data pipeline with explicit ingest, validate, transform and export stages. Add schema and CRS checks, reproducible configuration, structured logs, failure messages, pytest coverage for each stage and a before/after profiling note.'],
['HTTP and REST API Engineering','Client-server architecture, HTTP requests and responses, REST, methods, status codes, JSON and FastAPI.','A FastAPI service exposing documented health, observation list, observation detail and summary endpoints. Use Pydantic request/response schemas, correct HTTP methods and status codes, pagination or filtering, and tests for success, missing IDs and invalid input.'],
['Databases and PostgreSQL','Relational design, SQL, joins, keys, indexes, transactions, SQLAlchemy and migrations.','A PostgreSQL-backed observation service with a normalized schema, foreign keys, one useful index and SQLAlchemy models. Add an initial migration, seed data, CRUD endpoints, a join-based summary query and tests that exercise persistence and transaction rollback.'],
['Authentication and Backend Architecture','Authentication, authorization, password hashing, JWT, sessions, middleware, environment variables, validation and security.','An API with registration, login and protected resource routes. Hash passwords, issue and validate short-lived tokens, enforce ownership/role checks, load secrets from environment configuration, and test unauthenticated, unauthorized, malformed and successful requests. Document the threat boundaries and local setup.'],
['LLM Fundamentals','Transformers conceptually, tokens, context windows, inference, model types, APIs, structured output, model choice and Ollama.','A small model-comparison app that sends the same agricultural question to one hosted model and one Ollama local model. Normalize both outputs into a validated structured response, record latency and token/context constraints, handle unavailable providers, and document the model choice. Keep API keys outside the frontend.'],
['Tool Calling and Agent Harnesses','Function calling, tool schemas, agent loops, instructions, permissions, errors and human approval.','A bounded scientific assistant that can call exactly three typed Python tools: validate a CSV, calculate summary statistics and inspect raster metadata. Validate tool arguments, limit iterations, handle tool errors, log every call and require confirmation before any write or destructive action.'],
['RAG, Embeddings and Memory','Embeddings, vector search, chunking, RAG, pgvector, conversation and persistent memory, context compaction.','An agricultural research assistant that ingests a small cited document collection, chunks and embeds it, retrieves top matches using pgvector, and answers with source titles and passages. Include a no-match response, a retrieval inspection view and a test showing relevant sources are returned for representative questions.'],
['Agent Orchestration and Evaluation','LangGraph, agent state, multi-step workflows, AI evaluation, hallucination testing, retries and observability.','A LangGraph workflow that routes a user request through retrieval, a scientific tool when needed, answer drafting and citation checks. Define typed state, bounded retries and observable transitions; run a small evaluation set with expected evidence and record failure cases and scores.'],
['Systems Fundamentals','Processes, threads, concurrency, parallelism, sync/async execution, networking, transactions and caching.','A repeatable benchmark that processes the same dataset sequentially, with threads and with processes. Measure wall time and memory, explain the workload’s I/O or CPU profile, verify identical outputs, and document the bottleneck and the concurrency choice.'],
['Redis and Background Processing','Redis, caching, task queues, background jobs, message brokers, idempotency and retries.','A queued satellite-data processing flow with an API submission endpoint, Redis-backed worker, job status endpoint and result storage. Make job submission idempotent, retry transient failures with limits, expose failed-job details, and demonstrate a successful job plus a safe retry.'],
['Deployment and DevOps','Docker, Compose, CI/CD, cloud deployment, logging, monitoring and secrets management.','A containerized application with API, database and worker services in Docker Compose, health checks, persistent local data and environment-based secrets. Add CI to run tests and build images, structured logs and a deployment runbook; deploy to a chosen host and record the live URL and rollback steps.'],
['Independent Backend Project','Build an unrelated document workflow app with authentication, PostgreSQL, REST, file uploads, background work, AI summaries and deployment.','A deployed document workflow product built from a blank repository: authenticated upload/list/status/download APIs, PostgreSQL metadata, background text extraction, AI summaries with a provider boundary, tests, Docker deployment and user-facing documentation. Include a short demo flow and architecture diagram.'],
['Final Integration and Technical Defence','Integrate the minor project, test, document, diagram, deploy, review failures, demonstrate and practise architecture interviews.','A release candidate for the digital twin with the chosen end-to-end user flow working in the deployed environment. Deliver a passing test report, setup and operations docs, architecture and data-flow diagrams, known-limitations list, demo script, rollback/failure notes and a recorded practice defence of key decisions.']
];
const dates=[['2026-12-07','2026-12-13'],['2026-12-14','2026-12-20'],['2026-12-21','2026-12-27'],['2026-12-28','2027-01-03'],['2027-01-04','2027-01-10'],['2027-01-11','2027-01-17'],['2027-01-18','2027-01-24'],['2027-01-25','2027-01-31'],['2027-02-01','2027-02-07'],['2027-02-08','2027-02-14'],['2027-02-15','2027-02-21'],['2027-02-22','2027-02-28'],['2027-03-01','2027-03-07'],['2027-03-08','2027-03-14'],['2027-03-15','2027-03-21'],['2027-03-22','2027-03-28'],['2027-03-29','2027-04-04']];
const phaseFor=i=>i<5?0:i<8?1:i<12?2:3;
const dailyTitles=['Plan and set up the week','Learn core concepts','Practise with small exercises','Apply concepts to the project','Review, test and improve','Build the weekly deliverable','Reflect and plan next steps'];
const roadmap=weekInfo.map((w,i)=>({n:i+1,title:w[0],topics:w[1].split(', ').map(x=>x.trim().replace(/\.$/,'')),deliverable:w[2],start:dates[i][0],end:dates[i][1],phase:phaseFor(i),objectives:[`Understand the core concepts in ${w[0].toLowerCase()}.`,`Apply the topics in a practical, working deliverable.`,`Record decisions, gaps and questions in the engineering journal.`],exercises:window.weeklyExercises[i],days:dailyTitles.map((title,d)=>({title:`Day ${d+1}: ${title}`,description:d===5?`Complete a meaningful increment of the weekly deliverable: ${w[2]}`:d===6?'Review the week, capture lessons, and choose one topic to revisit.':`${title} for ${w[0]}. Pick one or two topics, make a small working example, and capture questions.` ,hours:phaseFor(i)===0?(d<5?5:4):3})),resources:[] }));
roadmap.forEach((week,i)=>{week.guide=window.weeklyGuides[i];week.extension=window.weeklyExtensions[i];week.overview=week.guide.overview;week.objectives=week.guide.objectives;week.topics=week.guide.topics;week.lessons=week.topics.map((topic,j)=>({title:topic.title,why:topic.detail,detail:topic.detail,objective:week.objectives[Math.min(j,week.objectives.length-1)],minutes:35,example:j===0?week.extension.example:null}));const hours=week.days.map(day=>day.hours),lessonNames=week.lessons.map(lesson=>lesson.title),split=Math.ceil(week.lessons.length/2),groups=[week.lessons.slice(0,split),week.lessons.slice(split)];week.days=[...groups.map((lessons,j)=>({title:`Lessons ${lessons[0]?`· ${lessons.map(l=>l.title).join(' · ')}`:''}`,description:`Study ${lessons.map(l=>l.title).join(' and ')}. ${lessons.map(l=>l.detail).join(' ')} Record one mechanism, one assumption and an example or diagram that connects these concepts to ${week.deliverable.split('.')[0]}.`,kind:'lesson',lessons:lessons.map(l=>week.lessons.indexOf(l))})),...week.exercises.map((exercise,j)=>({title:`Guided exercise ${j+1}: ${exercise.split(/[.;]/)[0]}`,description:`Implement and verify: ${exercise}`,kind:'exercise',exercise:j})),{title:`Problem set, knowledge check and submission: ${week.extension.assignment.title}`,description:`Complete the independent ${week.extension.category.toLowerCase()}: ${week.extension.assignment.statement} Then attempt the knowledge check and record the submission evidence.`,kind:'assessment'}].map((day,d)=>({...day,hours:hours[d]}))});
const skills=['Python','Git and Linux','Scientific Computing','Geospatial Engineering','Backend Engineering','Database Engineering','Systems Engineering','AI Engineering','AI-Assisted Development','Deployment and DevOps'];
const aiTopics=['Open versus closed models','Model APIs','Local inference','Ollama','Claude Code','OpenAI Codex','Agent harnesses','Tool calling','Context windows','Memory systems','Context compaction','RAG','Embeddings','Knowledge graphs','LangGraph','AI evaluation','Prompt engineering','AI-assisted debugging','Code review with AI agents'];
const projectNames=['Data ingestion','Satellite data processing','Geospatial preprocessing','Scientific model integration','Backend APIs','Database','Authentication','Agentic AI','RAG and knowledge retrieval','Digital twin interface','Testing','Deployment'];
const milestones=[{date:'2027-01-10',title:'Foundation milestone',desc:phases[0].milestone},{date:'2027-01-31',title:'Backend milestone',desc:phases[1].milestone},{date:'2027-02-28',title:'AI engineering milestone',desc:phases[2].milestone},{date:'2027-04-04',title:'Independent engineering target',desc:phases[3].milestone}];
const STORE='engineer-os-v1';
function blankState(){return {tasks:{},deliverables:{},hours:{},lessonCompletions:{},exerciseCompletions:{},bookmarks:{},lessonNotes:{},lessonQuestions:{},revealedHints:{},quizAnswers:{},assessments:{},assignmentSubmissions:{},activeLessons:{},weekTabs:{},journals:[],decisions:[],skills:{},projects:projectNames.map(name=>({name,status:'Not started',progress:0,owner:'Me',notes:'',tasks:'',deliverables:'',dependencies:''})),ai:Object.fromEntries(aiTopics.map(name=>[name,{level:'Beginner',status:'Not started',notes:'',exercise:'',link:''}])),milestones:{},weekNotes:{}}}
let state;try{state={...blankState(),...JSON.parse(localStorage.getItem(STORE)||'{}')};}catch{state=blankState()}
function save(){localStorage.setItem(STORE,JSON.stringify(state));syncMini()}
function esc(s=''){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
const dateObj=s=>new Date(s+'T12:00:00');
function fmt(s,opt={month:'short',day:'numeric'}){return dateObj(s).toLocaleDateString('en-US',opt)}
function range(w){return `${fmt(w.start)} – ${fmt(w.end)}`}
function todayISO(){let d=new Date(),off=d.getTimezoneOffset();return new Date(d.getTime()-off*60000).toISOString().slice(0,10)}
function currentWeek(){let d=todayISO();return roadmap.find(w=>d>=w.start&&d<=w.end)||roadmap.find(w=>d<w.start)||roadmap.at(-1)}
function totalTasks(){return roadmap.reduce((a,w)=>a+w.days.length,0)}
function doneTasks(){return Object.values(state.tasks).filter(Boolean).length}
function weekDone(n){return roadmap[n-1].days.filter((_,d)=>state.tasks[`${n}-${d}`]).length}
function weekUnits(n){let w=roadmap[n-1];return w.days.length+w.lessons.length+w.exercises.length+3}
function completedWeekUnits(n){let w=roadmap[n-1],lessons=w.lessons.filter((_,i)=>state.lessonCompletions[`${n}-${i}`]).length,exercises=w.exercises.filter((_,i)=>state.exerciseCompletions[`${n}-${i}`]).length,quiz=state.assessments[n]?.completed?1:0,assignment=state.assignmentSubmissions[n]?.submitted?1:0,deliverable=state.deliverables[n]?1:0;return weekDone(n)+lessons+exercises+quiz+assignment+deliverable}
function weekPercent(n){return Math.round(completedWeekUnits(n)/weekUnits(n)*100)}
function phasePercent(p){let ws=roadmap.filter(w=>w.phase===p);return Math.round(ws.reduce((a,w)=>a+weekPercent(w.n),0)/ws.length)}
function overall(){return Math.round(roadmap.reduce((sum,w)=>sum+completedWeekUnits(w.n),0)/roadmap.reduce((sum,w)=>sum+weekUnits(w.n),0)*100)}
function studyTarget(d=todayISO()){return d>='2026-12-07'&&d<='2027-01-07'?5:3}
function studySum(from,to){return Object.entries(state.hours).filter(([d])=>d>=from&&d<=to).reduce((a,[,v])=>a+(Number(v)||0),0)}
function streak(){let n=0,d=dateObj(todayISO());while(true){let k=d.toISOString().slice(0,10);if((+state.hours[k]||0)<=0)break;n++;d.setDate(d.getDate()-1)}return n}
function syncMini(){let p=overall();document.querySelector('#mini-progress').textContent=p+'%';document.querySelector('#mini-bar').style.width=p+'%'}
function phaseLabel(p){return phases[p].name}
function statusClass(s){return s.toLowerCase().replaceAll(' ','-')}
function taskKey(w,d){return `${w}-${d}`}
function render(){let raw=location.hash.slice(1)||'dashboard';let detail=raw.match(/^week-(\d+)$/);let page=detail?'week':raw;const names={dashboard:'OVERVIEW',roadmap:'ROADMAP',projects:'PROJECT TRACKER','ai-mastery':'AI TOOL MASTERY',journal:'ENGINEERING JOURNAL',decisions:'DECISION LOG',analytics:'PROGRESS ANALYTICS',week:'WEEKLY DETAIL'};document.querySelector('#crumb').textContent=names[page]||'OVERVIEW';document.querySelectorAll('.nav-item[data-page]').forEach(a=>a.classList.toggle('active',a.dataset.page===page||page==='week'&&a.dataset.page==='roadmap'));document.querySelector('#today-date').textContent=new Date().toLocaleDateString('en-US',{weekday:'short',month:'short',day:'numeric',year:'numeric'}).toUpperCase();let root=document.querySelector('#content');root.innerHTML=detail?renderWeek(+detail[1]):({dashboard:renderDashboard,roadmap:renderRoadmap,projects:renderProjects,'ai-mastery':renderAI,journal:renderJournal,decisions:renderDecisions,analytics:renderAnalytics}[page]||renderDashboard)();syncMini()}
const renderBase=render;render=function(){renderBase();const match=location.hash.match(/^#week-(\d+)$/);if(!match)return;const n=+match[1],section=[...document.querySelectorAll('.card .page-section')].find(x=>x.querySelector('.card-kicker')?.textContent==='WEEKLY DELIVERABLE');if(section){const label=document.createElement('label');label.className='week-deliverable';label.style.cssText='margin-top:8px;display:flex;gap:10px;align-items:center';label.innerHTML=`<input type="checkbox" class="check" data-deliverable="${n}" ${state.deliverables[n]?'checked':''}><span>Mark this deliverable complete</span>`;section.appendChild(label)}};
function progressCard(title,pct,caption,icon){return `<article class="card"><div class="card-header"><span class="card-title">${title}</span><span class="metric-icon">${icon}</span></div><div class="stat-line"><div class="metric">${pct}<span class="metric-suffix">%</span></div></div><div class="progress-track"><span style="width:${pct}%"></span></div><div class="metric-caption">${caption}</div></article>`}
function renderDashboard(){let w=currentWeek(),p=phases[w.phase],hours=Number(state.hours[todayISO()]||0),from=todayISO(),start=dateObj(from);start.setDate(start.getDate()-6);let avg=studySum(start.toISOString().slice(0,10),from)/7;return `<div class="hero-row"><div><div class="eyebrow">MONDAY, NOVEMBER 16, 2026 · YOUR JOURNEY STARTS DECEMBER 7</div><h1 class="page-title">Good morning, Engineer.</h1><p class="page-sub">Your next milestone is one step away.</p></div><div class="hero-date">${fmt(todayISO(),{weekday:'long',month:'long',day:'numeric',year:'numeric'})}</div></div>
<div class="grid stats-grid">${progressCard('ROADMAP PROGRESS',overall(),`${doneTasks()} tasks complete · ${totalTasks()-doneTasks()} remaining`,'◒')}<article class="card"><div class="card-header"><span class="card-title">WEEKS COMPLETED</span><span class="metric-icon">⌁</span></div><div class="metric">${roadmap.filter(w=>weekPercent(w.n)===100).length}<span class="metric-suffix"> / 17</span></div><div class="metric-caption">Weeks count when the lessons, exercises, assessment and deliverable are complete</div><div class="tiny-bars">${roadmap.slice(0,12).map(w=>`<span style="height:${Math.max(16,weekPercent(w.n)*.3)}%"></span>`).join('')}</div></article><article class="card"><div class="card-header"><span class="card-title">STUDY STREAK</span><span class="metric-icon">↗</span></div><div class="metric">${streak()}<span class="metric-suffix"> days</span></div><div class="metric-caption">Log study hours to grow your streak</div></article><article class="card"><div class="card-header"><span class="card-title">HOURS THIS WEEK</span><span class="metric-icon">◷</span></div><div class="metric">${studySum(weekStart(from),from).toFixed(1)}<span class="metric-suffix"> hrs</span></div><div class="metric-caption">Target: ${studyTarget(from)} hours today</div></article></div>
<div class="grid main-grid"><article class="card phase-card"><div class="card-header"><span class="card-kicker">PHASE ${w.phase+1} · CURRENT PHASE</span><span class="tag">${phasePercent(w.phase)}% COMPLETE</span></div><div class="phase-name">${phaseLabel(w.phase)}</div><div class="phase-meta">${fmt(p.start,{month:'long',day:'numeric'})} — ${fmt(p.end,{month:'long',day:'numeric',year:'numeric'})}</div><p class="phase-desc">${p.desc}</p><div class="progress-track"><span style="width:${phasePercent(w.phase)}%"></span></div><div class="phase-foot"><span>NEXT MILESTONE</span><strong>${esc(p.milestone)}</strong></div></article><article class="card current-week"><div class="card-header"><span class="card-kicker">${todayISO()<w.start?'UP NEXT':'CURRENT WEEK'} · WEEK ${w.n}</span><a class="text-link" href="#week-${w.n}">OPEN WEEK →</a></div><h3 class="week-heading">${esc(w.title)}</h3><div class="week-date">${range(w)} · ${completedWeekUnits(w.n)}/${weekUnits(w.n)} LEARNING UNITS</div><ul class="week-objectives">${w.objectives.slice(0,2).map(o=>`<li>${esc(o)}</li>`).join('')}</ul><div class="week-deliverable"><b>WEEKLY DELIVERABLE</b>${esc(w.deliverable.split(".")[0]+".")}</div></article></div>
<div class="section-heading"><h2>Daily study tracker</h2><span class="card-kicker">CONSISTENCY BUILDS MOMENTUM</span></div><div class="grid study-grid"><article class="card study-card"><div><div class="card-kicker">TODAY'S TARGET · ${studyTarget()} HOURS</div><div class="study-big">${hours.toFixed(1)} <span>/ ${studyTarget()} hrs</span></div><div class="study-sub">7 day average: ${avg.toFixed(1)} hrs · ${streak()} day streak</div><div class="streak">${Array.from({length:7},(_,i)=>{let d=dateObj(todayISO());d.setDate(d.getDate()-(6-i));let k=d.toISOString().slice(0,10);return `<span class="${Number(state.hours[k]||0)>0?'on':''}" title="${fmt(k)}: ${state.hours[k]||0}h"></span>`}).join('')}</div></div><div style="display:grid;gap:7px"><input class="study-input" id="hours-input" type="number" step="0.25" min="0" max="24" value="${hours}" aria-label="Hours studied today"><button class="btn btn-primary" data-action="log-hours">Log hours</button></div></article><article class="card"><div class="card-header"><span class="card-title">RECENT STUDY HISTORY</span><span class="card-kicker">HOURS / DAY</span></div>${studyHistory()}</article></div>
<div class="section-heading"><h2>Skill progress</h2><a class="text-link" href="#analytics">VIEW ANALYTICS →</a></div><article class="card"><div class="grid skills-grid">${skills.map(s=>skillBar(s)).join('')}</div><p class="metric-caption">Skills are derived from completed week tasks. Adjust them manually in Analytics.</p></article>
<div class="section-heading"><h2>Upcoming milestones</h2><a class="text-link" href="#roadmap">VIEW ROADMAP →</a></div><article class="card">${milestones.map((m,i)=>`<div class="milestone-row"><span class="m-date">${fmt(m.date,{month:'short',day:'numeric'})}</span><div class="m-copy">${esc(m.title)} <small>${esc(m.desc)}</small></div><input class="check" type="checkbox" data-milestone="${i}" ${state.milestones[i]?'checked':''} aria-label="Complete ${esc(m.title)}"></div>`).join('')}</article>`}
function weekStart(d){let x=dateObj(d),day=x.getDay();x.setDate(x.getDate()-((day+6)%7));return x.toISOString().slice(0,10)}
function skillValue(s){if(state.skills[s]!==undefined)return Number(state.skills[s]);let relevant=({Python:[0,1], 'Git and Linux':[0,1], 'Scientific Computing':[2,4], 'Geospatial Engineering':[3,4], 'Backend Engineering':[5,6,7], 'Database Engineering':[6,7], 'Systems Engineering':[12,13], 'AI Engineering':[8,9,10,11], 'AI-Assisted Development':[9,11,15], 'Deployment and DevOps':[14,16]})[s]||[];return relevant.length?Math.round(relevant.reduce((a,n)=>a+weekPercent(n+1),0)/relevant.length):0}
function skillBar(s,editable=false){let v=skillValue(s);return `<div class="skill"><div class="skill-top"><span>${esc(s)}</span><span>${editable?`<input class="row-input" style="width:48px;text-align:center" type="number" min="0" max="100" value="${v}" data-skill="${esc(s)}">`:`${v}%`}</span></div><div class="skill-track"><span style="width:${v}%"></span></div></div>`}
function studyHistory(){let a=[];for(let i=6;i>=0;i--){let d=dateObj(todayISO());d.setDate(d.getDate()-i);let k=d.toISOString().slice(0,10);a.push([k,Number(state.hours[k]||0)])}let max=Math.max(1,...a.map(x=>x[1]));return `<div class="chart">${a.map(([d,v])=>`<div class="chart-bar-wrap"><span class="chart-value">${v||''}</span><div class="chart-bar" style="height:${v?Math.max(4,v/max*80):2}px;opacity:${v?1:.3}"></div><span class="chart-label">${dateObj(d).toLocaleDateString('en-US',{weekday:'narrow'})}</span></div>`).join('')}</div>`}
function renderRoadmap(){return `<div class="hero-row"><div><div class="eyebrow">DECEMBER 07, 2026 — APRIL 04, 2027</div><h1 class="page-title">The roadmap</h1><p class="page-sub">A 17 week progression from foundations to independent engineering.</p></div><div class="page-toolbar"><input class="search" id="roadmap-search" placeholder="Search weeks or topics…"><select class="select" id="phase-filter"><option value="all">All phases</option>${phases.map((p,i)=>`<option value="${i}">Phase ${i+1}: ${esc(p.name)}</option>`).join('')}</select></div></div>${phases.map((p,pi)=>`<section class="phase-block" data-phase-block="${pi}"><div class="phase-banner"><span class="phase-num">0${pi+1}</span><strong>${esc(p.name)}</strong><small>${fmt(p.start,{month:'short',day:'numeric'})} — ${fmt(p.end,{month:'short',day:'numeric'})} · ${phasePercent(pi)}%</small></div><div class="week-list">${roadmap.filter(w=>w.phase===pi).map(w=>weekCard(w)).join('')}</div></section>`).join('')}`}
function weekCard(w){return `<a class="week-card" href="#week-${w.n}" data-week-search="${esc((w.title+' '+w.topics.join(' ')).toLowerCase())}"><span class="week-index">${String(w.n).padStart(2,'0')}</span><span><h3>${esc(w.title)}</h3><p>${range(w)} · ${esc(w.deliverable.split(".")[0]+".")}</p></span><span class="week-card-right"><small>${weekDone(w.n)}/7 TASKS</small><span class="mini-progress"><span style="width:${weekPercent(w.n)}%"></span></span></span></a>`}
function renderWeek(n){let w=roadmap[n-1];if(!w)return '<div class="empty">Week not found.</div>';return `<button class="detail-back" onclick="location.hash='#roadmap'">← BACK TO ROADMAP</button><div class="hero-row"><div><div class="eyebrow">PHASE ${w.phase+1} · ${phaseLabel(w.phase).toUpperCase()} · WEEK ${n}</div><h1 class="page-title">${esc(w.title)}</h1><p class="page-sub">${range(w)} · ${weekDone(n)}/7 daily tasks complete</p></div><span class="tag">${weekPercent(n)}% COMPLETE</span></div><div class="progress-track" style="margin:0 0 18px"><span style="width:${weekPercent(n)}%"></span></div><div class="grid detail-layout"><div><article class="card"><div class="card-header"><span class="card-title">WEEK OVERVIEW</span><span class="card-kicker">EST. ${w.days.reduce((a,d)=>a+d.hours,0)} HOURS</span></div><p class="page-sub" style="line-height:1.8">${esc(phases[w.phase].desc)}</p><div class="page-section"><div class="card-kicker">LEARNING OBJECTIVES</div>${w.objectives.map(o=>`<div class="detail-topic"><span class="topic-bullet">✦</span>${esc(o)}</div>`).join('')}</div><div class="page-section"><div class="card-kicker">TOPICS TO LEARN</div><div class="grid skills-grid" style="gap:0 20px">${w.topics.map(t=>`<div class="detail-topic"><span class="topic-bullet">·</span>${esc(t)}</div>`).join('')}</div></div><div class="page-section"><div class="card-kicker">PRACTICAL CODING EXERCISES</div>${w.exercises.map(e=>`<div class="detail-topic"><span class="topic-bullet">⌘</span>${esc(e)}</div>`).join('')}</div><div class="page-section"><div class="card-kicker">WEEKLY DELIVERABLE</div><div class="week-deliverable" style="margin-top:8px">${esc(w.deliverable)}</div></div></article><article class="card page-section"><div class="card-header"><span class="card-title">DAILY TASK CHECKLIST</span><span class="card-kicker">TASKS STAY OPEN UNTIL YOU CHECK THEM OFF</span></div>${w.days.map((d,i)=>`<div class="daily-row"><span class="day-badge">D${i+1}</span><div><h4>${esc(d.title)}</h4><small>${esc(d.description)} · ${d.hours}h target</small></div><input type="checkbox" class="check" data-task="${taskKey(n,i)}" ${state.tasks[taskKey(n,i)]?'checked':''}></div>`).join('')}</article></div><aside><article class="card"><div class="card-header"><span class="card-title">NOTES & REFLECTIONS</span><span class="card-kicker">PRIVATE TO THIS WEEK</span></div><textarea class="field" id="week-notes" style="width:100%;min-height:180px;background:#0b121e;color:#edf2fa;border:1px solid #293548;border-radius:7px;padding:10px;font-size:10px" placeholder="What clicked? What needs another pass? What will you build next?">${esc(state.weekNotes[n]||'')}</textarea><button class="btn btn-primary" data-action="save-week-notes" data-week="${n}">Save reflection</button></article><article class="card page-section"><div class="card-header"><span class="card-title">COMPLETION CRITERIA</span></div><div class="detail-topic"><span class="topic-bullet">○</span>All seven daily tasks reviewed and checked as completed.</div><div class="detail-topic"><span class="topic-bullet">○</span>Deliverable is complete and can be demonstrated.</div><div class="detail-topic"><span class="topic-bullet">○</span>Write down one lesson and one remaining question.</div></article><article class="card page-section"><div class="card-header"><span class="card-title">RESOURCES</span><span class="card-kicker">ADD YOUR LINKS</span></div><input class="row-input" id="resource-link" placeholder="Paste a documentation URL"><button class="btn btn-quiet" style="margin-top:8px" data-action="add-resource" data-week="${n}">Add resource</button>${w.resources.map((r,i)=>`<div class="detail-topic"><a href="${esc(r)}" target="_blank" rel="noreferrer">${esc(r)}</a><button class="text-link" data-action="remove-resource" data-week="${n}" data-index="${i}">×</button></div>`).join('')}</article></aside></div>`}
function renderProjects(){return `<div class="hero-row"><div><div class="eyebrow">MINOR PROJECT · PERSONAL + TEAM WORKSTREAMS</div><h1 class="page-title">Project tracker</h1><p class="page-sub">Coupled GEO–LEO Radiative Transfer Physics and Agentic AI-based Agrometeorological Digital Twin for Drought-Resilient Farming.</p></div><button class="btn btn-primary" data-action="add-project">＋ Add workstream</button></div><article class="card"><div class="card-header"><span class="card-title">WORKSTREAMS</span><span class="card-kicker">NO STATUS IS PRESET AS COMPLETE</span></div><div style="overflow:auto"><table class="table"><thead><tr><th>WORKSTREAM</th><th>STATUS</th><th>PROGRESS</th><th>OWNER</th><th>NOTES</th><th></th></tr></thead><tbody>${state.projects.map((p,i)=>`<tr><td style="min-width:155px"><b>${esc(p.name)}</b><details style="margin-top:7px"><summary class="muted">Tasks · deliverables · deps</summary><div class="field"><label>TASKS</label><textarea class="row-input" data-project="${i}" data-key="tasks">${esc(p.tasks)}</textarea></div><div class="field"><label>DELIVERABLES</label><textarea class="row-input" data-project="${i}" data-key="deliverables">${esc(p.deliverables)}</textarea></div><div class="field"><label>DEPENDENCIES</label><input class="row-input" data-project="${i}" data-key="dependencies" value="${esc(p.dependencies)}"></div></details></td><td><select class="select" data-project="${i}" data-key="status"><option ${p.status==='Not started'?'selected':''}>Not started</option><option ${p.status==='In progress'?'selected':''}>In progress</option><option ${p.status==='Blocked'?'selected':''}>Blocked</option><option ${p.status==='Complete'?'selected':''}>Complete</option></select></td><td><input class="row-input" type="number" min="0" max="100" value="${p.progress}" data-project="${i}" data-key="progress"></td><td><select class="select" data-project="${i}" data-key="owner"><option ${p.owner==='Me'?'selected':''}>Me</option><option ${p.owner==='Teammate'?'selected':''}>Teammate</option><option ${p.owner==='Shared'?'selected':''}>Shared</option><option ${p.owner==='Unassigned'?'selected':''}>Unassigned</option></select></td><td style="min-width:160px"><input class="row-input" data-project="${i}" data-key="notes" value="${esc(p.notes)}" placeholder="Add a note"></td><td><button class="text-link danger" data-action="delete-project" data-index="${i}">Remove</button></td></tr>`).join('')}</tbody></table></div></article>`}
function renderAI(){return `<div class="hero-row"><div><div class="eyebrow">PRACTICAL FLUENCY · NO ADVANCED CUDA REQUIRED</div><h1 class="page-title">AI tool mastery</h1><p class="page-sub">Build hands-on understanding of the tools and patterns behind useful AI applications.</p></div><input class="search" id="ai-search" placeholder="Search topics…"></div><article class="card"><div class="card-header"><span class="card-title">LEARNING TRACKER</span><span class="card-kicker">EDIT LEVEL, STATUS, NOTES AND EXERCISES</span></div><div style="overflow:auto"><table class="table"><thead><tr><th>TOPIC</th><th>LEVEL</th><th>STATUS</th><th>EXERCISE / NOTES</th><th>DOC LINK</th></tr></thead><tbody>${aiTopics.map((t,i)=>{let a=state.ai[t]||{};return `<tr data-ai-row="${esc(t.toLowerCase())}"><td><b>${esc(t)}</b></td><td><select class="select" data-ai="${esc(t)}" data-key="level"><option ${a.level==='Beginner'?'selected':''}>Beginner</option><option ${a.level==='Intermediate'?'selected':''}>Intermediate</option><option ${a.level==='Advanced'?'selected':''}>Advanced</option></select></td><td><select class="select" data-ai="${esc(t)}" data-key="status"><option ${a.status==='Not started'?'selected':''}>Not started</option><option ${a.status==='Learning'?'selected':''}>Learning</option><option ${a.status==='Practised'?'selected':''}>Practised</option><option ${a.status==='Comfortable'?'selected':''}>Comfortable</option></select></td><td style="min-width:180px"><input class="row-input" data-ai="${esc(t)}" data-key="exercise" value="${esc(a.exercise||'')}" placeholder="Exercise or notes"></td><td><input class="row-input" data-ai="${esc(t)}" data-key="link" value="${esc(a.link||'')}" placeholder="URL"></td></tr>`}).join('')}</tbody></table></div></article><div class="section-heading"><h2>Topic notes</h2></div><div class="grid skills-grid">${aiTopics.map(t=>`<article class="card"><div class="card-header"><span class="card-title">${esc(t)}</span><span class="status ${statusClass(state.ai[t]?.status||'Not started')}">${esc(state.ai[t]?.status||'Not started')}</span></div><textarea class="row-input" data-ai="${esc(t)}" data-key="notes" placeholder="Capture what you learn…">${esc(state.ai[t]?.notes||'')}</textarea></article>`).join('')}</div>`}
function renderJournal(){return `<div class="hero-row"><div><div class="eyebrow">LEARN IN PUBLIC TO YOUR FUTURE SELF</div><h1 class="page-title">Engineering journal</h1><p class="page-sub">Capture what you learned, built, debugged, and decided.</p></div><input class="search" id="journal-search" placeholder="Search journal…"></div><div class="grid two-col"><article class="card"><div class="card-header"><span class="card-title">NEW JOURNAL ENTRY</span><span class="card-kicker">${fmt(todayISO(),{weekday:'short',month:'short',day:'numeric'})}</span></div><div class="form-grid"><div class="field"><label>WHAT I LEARNED TODAY</label><textarea id="j-learned" placeholder="A concept that makes more sense now…"></textarea></div><div class="field"><label>WHAT I BUILT</label><textarea id="j-built" placeholder="Code, experiment, or deliverable…"></textarea></div><div class="field"><label>PROBLEMS & HOW I SOLVED THEM</label><textarea id="j-problems" placeholder="The obstacle and the fix…"></textarea></div><div class="field"><label>WHAT AI HELPED WITH / WHERE I DISAGREED</label><textarea id="j-ai" placeholder="What helped? What needed verification?…"></textarea></div><div class="field"><label>TECHNICAL DECISIONS</label><textarea id="j-decisions" placeholder="A choice and the reason…"></textarea></div><div class="field"><label>WHAT TO REVISIT</label><textarea id="j-revisit" placeholder="Gaps, questions, or a future experiment…"></textarea></div></div><button class="btn btn-primary" data-action="save-journal">Save entry</button></article><article class="card"><div class="card-header"><span class="card-title">JOURNAL HISTORY</span><span class="card-kicker">${state.journals.length} ENTRIES</span></div><div id="journal-list">${journalEntries(state.journals)}</div></article></div>`}
function journalEntries(entries){if(!entries.length)return '<div class="empty">No journal entries yet. Your first reflection starts here.</div>';return [...entries].sort((a,b)=>b.date.localeCompare(a.date)).map(j=>`<div class="journal-item" data-journal="${esc(Object.values(j).join(' ').toLowerCase())}"><time>${fmt(j.date,{weekday:'short',month:'short',day:'numeric',year:'numeric'})}</time>${Object.entries({Learned:j.learned,Built:j.built,Problems:j.problems,AI:j.ai,Decisions:j.decisions,Revisit:j.revisit}).filter(([,v])=>v).map(([k,v])=>`<h3>${k}</h3><p>${esc(v)}</p>`).join('')}<button class="text-link danger" data-action="delete-journal" data-id="${j.id}">Delete</button></div>`).join('')}
function renderDecisions(){return `<div class="hero-row"><div><div class="eyebrow">EXPLAIN THE WHY, NOT JUST THE WHAT</div><h1 class="page-title">Engineering decision log</h1><p class="page-sub">Practise defending architecture and implementation choices with a clear record.</p></div><button class="btn btn-primary" data-action="new-decision">＋ Record a decision</button></div>${state.decisions.length?`<div class="grid">${[...state.decisions].reverse().map(d=>`<article class="card"><div class="card-header"><span class="card-title">${esc(d.title)}</span><span class="card-kicker">${fmt(d.date,{month:'short',day:'numeric',year:'numeric'})}</span></div><div class="grid skills-grid">${[['Problem',d.problem],['Requirements',d.requirements],['Alternatives',d.alternatives],['Selected approach',d.selected],['Reasoning',d.reasoning],['Trade-offs',d.tradeoffs],['Validation',d.validation],['Future improvements',d.future]].filter(x=>x[1]).map(([k,v])=>`<div class="detail-topic"><b>${k}:</b>&nbsp; ${esc(v)}</div>`).join('')}</div><button class="text-link danger" data-action="delete-decision" data-id="${d.id}">Delete entry</button></article>`).join('')}</div>`:'<article class="card empty">No decisions recorded yet. Start with a small architecture choice and write down the alternatives you considered.</article>'}`}
function renderAnalytics(){let weekly=roadmap.map(w=>weekPercent(w.n));let vals=Object.entries(state.hours).sort(([a],[b])=>a.localeCompare(b)).slice(-14);return `<div class="hero-row"><div><div class="eyebrow">MEASURE WHAT YOU ACTUALLY DID</div><h1 class="page-title">Progress analytics</h1><p class="page-sub">Every metric is calculated from your checked tasks and recorded study hours.</p></div><span class="tag">${doneTasks()} COMPLETED TASKS</span></div><div class="grid stats-grid">${progressCard('OVERALL ROADMAP',overall(),`${doneTasks()} of ${totalTasks()} daily tasks complete`,'◒')}<article class="card"><div class="card-header"><span class="card-title">CURRENT STREAK</span><span class="metric-icon">↗</span></div><div class="metric">${streak()}<span class="metric-suffix"> days</span></div><div class="metric-caption">Consecutive days with logged study time</div></article><article class="card"><div class="card-header"><span class="card-title">TOTAL STUDY HOURS</span><span class="metric-icon">◷</span></div><div class="metric">${Object.values(state.hours).reduce((a,v)=>a+(Number(v)||0),0).toFixed(1)}<span class="metric-suffix"> hrs</span></div><div class="metric-caption">Across ${Object.keys(state.hours).length} logged days</div></article><article class="card"><div class="card-header"><span class="card-title">DELIVERABLES</span><span class="metric-icon">◈</span></div><div class="metric">${roadmap.filter(w=>weekPercent(w.n)===100).length}<span class="metric-suffix"> / 17</span></div><div class="metric-caption">A week counts when all seven daily tasks are checked</div></article></div><div class="grid two-col"><article class="card"><div class="card-header"><span class="card-title">WEEKLY COMPLETION</span><span class="card-kicker">TASKS DONE / WEEK</span></div><div class="chart">${roadmap.map((w,i)=>`<div class="chart-bar-wrap"><span class="chart-value">${weekly[i]}%</span><div class="chart-bar" style="height:${Math.max(2,weekly[i]*1.05)}px;opacity:${weekly[i]?1:.4}" title="${esc(w.title)}: ${weekly[i]}%"></div><span class="chart-label">W${w.n}</span></div>`).join('')}</div></article><article class="card"><div class="card-header"><span class="card-title">PHASE COMPLETION</span></div>${phases.map((p,i)=>`<div style="margin:0 0 16px"><div class="skill-top"><span>${esc(p.name)}</span><span>${phasePercent(i)}%</span></div><div class="skill-track"><span style="width:${phasePercent(i)}%"></span></div></div>`).join('')}</article><article class="card"><div class="card-header"><span class="card-title">DAILY STUDY HOURS</span><span class="card-kicker">LAST 14 LOGGED DAYS</span></div>${vals.length?`<div class="chart">${vals.map(([d,v])=>`<div class="chart-bar-wrap"><span class="chart-value">${Number(v).toFixed(1)}</span><div class="chart-bar" style="height:${Math.max(3,Math.min(95,Number(v)*12))}px"></div><span class="chart-label">${fmt(d,{month:'numeric',day:'numeric'})}</span></div>`).join('')}</div>`:'<div class="empty">Log study hours to see your history.</div>'}</article><article class="card"><div class="card-header"><span class="card-title">SKILL DEVELOPMENT</span><span class="card-kicker">EDIT VALUES</span></div><div class="grid skills-grid">${skills.map(s=>skillBar(s,true)).join('')}</div></article></div><div class="section-heading"><h2>Outstanding daily tasks</h2><span class="card-kicker">${totalTasks()-doneTasks()} TO GO</span></div><article class="card">${roadmap.flatMap(w=>w.days.map((d,i)=>({w,d,i}))).filter(x=>!state.tasks[taskKey(x.w.n,x.i)]).slice(0,12).map(x=>`<div class="daily-row"><span class="day-badge">W${x.w.n}</span><div><h4>${esc(x.d.title)}</h4><small>${esc(x.w.title)} · ${x.d.hours}h</small></div><a class="text-link" href="#week-${x.w.n}">OPEN →</a></div>`).join('')||'<div class="empty">All daily tasks are complete. Outstanding tasks will appear here.</div>'}</article>`}
function showToast(msg){let t=document.querySelector('#toast');t.textContent=msg;t.classList.add('show');setTimeout(()=>t.classList.remove('show'),2200)}
function modal(title,body,actionLabel='Save'){let old=document.querySelector('.modal-backdrop');if(old)old.remove();document.body.insertAdjacentHTML('beforeend',`<div class="modal-backdrop"><div class="modal"><div class="modal-head"><h2>${title}</h2><button class="icon-btn" data-action="close-modal">×</button></div>${body}<div style="display:flex;justify-content:flex-end;gap:8px;margin-top:12px"><button class="btn btn-quiet" data-action="close-modal">Cancel</button><button class="btn btn-primary" data-action="modal-save">${actionLabel}</button></div></div></div>`)}
document.addEventListener('click',e=>{let a=e.target.closest('[data-action]');if(!a)return;let action=a.dataset.action;
 if(action==='log-hours'){let v=Math.max(0,Math.min(24,Number(document.querySelector('#hours-input').value)||0));state.hours[todayISO()]=v;save();render();showToast('Study time saved.')}
 if(action==='save-week-notes'){state.weekNotes[a.dataset.week]=document.querySelector('#week-notes').value;save();showToast('Reflection saved.')}
 if(action==='add-resource'){let n=+a.dataset.week,v=document.querySelector('#resource-link').value.trim();if(v){roadmap[n-1].resources.push(v);/* resources are stored separately below */state.weekResources=state.weekResources||{};state.weekResources[n]=roadmap[n-1].resources;save();render();showToast('Resource added.') }}
 if(action==='remove-resource'){let n=+a.dataset.week;roadmap[n-1].resources.splice(+a.dataset.index,1);state.weekResources[n]=roadmap[n-1].resources;save();render()}
 if(action==='save-journal'){let vals=['learned','built','problems','ai','decisions','revisit'].map(k=>document.querySelector('#j-'+k).value.trim());if(!vals.some(Boolean)){showToast('Write a note before saving.');return}state.journals.push({id:crypto.randomUUID(),date:todayISO(),learned:vals[0],built:vals[1],problems:vals[2],ai:vals[3],decisions:vals[4],revisit:vals[5]});save();render();showToast('Journal entry saved.')}
 if(action==='delete-journal'){state.journals=state.journals.filter(j=>j.id!==a.dataset.id);save();render()}
 if(action==='new-decision'){modal('Record an engineering decision',`<div class="form-grid">${[['title','Decision title'],['problem','Problem'],['requirements','Requirements'],['alternatives','Alternatives considered'],['selected','Selected approach'],['reasoning','Reasoning'],['tradeoffs','Trade-offs'],['validation','Validation'],['future','Future improvements']].map(([id,label])=>`<div class="field"><label>${label.toUpperCase()}</label><textarea id="d-${id}" ${id==='title'?'placeholder="Short, specific title"':''}></textarea></div>`).join('')}</div>`)}
 if(action==='modal-save'){let modalEl=document.querySelector('.modal-backdrop');if(!modalEl)return;let title=modalEl.querySelector('#d-title');if(title){let get=k=>modalEl.querySelector('#d-'+k).value.trim();if(!get('title')){showToast('Add a decision title.');return}state.decisions.push({id:crypto.randomUUID(),date:todayISO(),...Object.fromEntries(['title','problem','requirements','alternatives','selected','reasoning','tradeoffs','validation','future'].map(k=>[k,get(k)]))});save();modalEl.remove();render();showToast('Decision recorded.')}}
 if(action==='delete-decision'){state.decisions=state.decisions.filter(d=>d.id!==a.dataset.id);save();render()}
 if(action==='add-project'){state.projects.push({name:'New workstream',status:'Not started',progress:0,owner:'Unassigned',notes:'',tasks:'',deliverables:'',dependencies:''});save();render()}
 if(action==='delete-project'){state.projects.splice(+a.dataset.index,1);save();render()}
 if(action==='close-modal')document.querySelector('.modal-backdrop')?.remove();
});
document.addEventListener('change',e=>{let t=e.target;if(t.matches('[data-task]')){state.tasks[t.dataset.task]=t.checked;save();render()}else if(t.matches('[data-deliverable]')){state.deliverables[t.dataset.deliverable]=t.checked;save();render()}else if(t.matches('[data-milestone]')){state.milestones[t.dataset.milestone]=t.checked;save();showToast('Milestone updated.')}else if(t.matches('[data-project]')){let p=state.projects[+t.dataset.project],k=t.dataset.key;p[k]=k==='progress'?Math.max(0,Math.min(100,+t.value||0)):t.value;save()}else if(t.matches('[data-ai]')){let r=state.ai[t.dataset.ai];r[t.dataset.key]=t.value;save()}else if(t.matches('[data-skill]')){state.skills[t.dataset.skill]=Math.max(0,Math.min(100,+t.value||0));save();render()}});
document.addEventListener('input',e=>{let t=e.target;if(t.id==='roadmap-search'){let q=t.value.toLowerCase();document.querySelectorAll('[data-week-search]').forEach(x=>x.style.display=x.dataset.weekSearch.includes(q)?'grid':'none')}if(t.id==='phase-filter'){document.querySelectorAll('[data-phase-block]').forEach(x=>x.style.display=t.value==='all'||t.dataset.phaseBlock===t.value?'':'none')}if(t.id==='ai-search'){let q=t.value.toLowerCase();document.querySelectorAll('[data-ai-row]').forEach(x=>x.style.display=x.dataset.aiRow.includes(q)?'':'none')}if(t.id==='journal-search'){let q=t.value.toLowerCase();document.querySelectorAll('[data-journal]').forEach(x=>x.style.display=x.dataset.journal.includes(q)?'':'none')}if(t.matches('[data-project]')&&t.tagName==='INPUT'){let p=state.projects[+t.dataset.project];p[t.dataset.key]=t.dataset.key==='progress'?Math.max(0,Math.min(100,+t.value||0)):t.value;save()}if(t.matches('[data-ai]')&&t.tagName==='INPUT'){state.ai[t.dataset.ai][t.dataset.key]=t.value;save()}if(t.matches('[data-ai]')&&t.tagName==='TEXTAREA'){state.ai[t.dataset.ai][t.dataset.key]=t.value;save()}});
document.querySelector('#nav').addEventListener('click',e=>{if(e.target.closest('a'))document.querySelector('#sidebar').classList.remove('open')});document.querySelector('#menu-btn').addEventListener('click',()=>document.querySelector('#sidebar').classList.toggle('open'));window.addEventListener('hashchange',render);
document.querySelector('#backup-btn').addEventListener('click',()=>modal('Export or restore your progress',`<p class="page-sub">Your tasks, hours, projects, journal, decisions and settings are stored in this browser. Export a backup to keep a copy or move to another browser.</p><div style="display:flex;gap:8px;margin-top:18px"><button class="btn btn-primary" data-action="export">Download backup</button><button class="btn btn-quiet" data-action="restore">Choose backup file</button></div>`,'Done'));
document.addEventListener('click',e=>{if(e.target.dataset.action==='export'){let blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='engineer-os-backup-'+todayISO()+'.json';a.click();URL.revokeObjectURL(url);showToast('Backup downloaded.')}if(e.target.dataset.action==='restore')document.querySelector('#restore-file').click()});
document.querySelector('#restore-file').addEventListener('change',async e=>{let f=e.target.files[0];if(!f)return;try{let x=JSON.parse(await f.text());state={...blankState(),...x};save();document.querySelector('.modal-backdrop')?.remove();render();showToast('Backup restored.')}catch{showToast('That backup file could not be read.')}e.target.value=''});
document.querySelector('#settings-btn').addEventListener('click',()=>modal('Settings',`<p class="page-sub">ENGINEER OS saves progress locally in this browser. Export a JSON backup before switching browsers or clearing site data.</p><div class="settings-row"><span>Journey start</span><b>December 7, 2026</b></div><div class="settings-row"><span>Journey end</span><b>April 4, 2027</b></div><div class="settings-row"><span>Persistence</span><b>Browser local storage</b></div><div style="margin-top:14px"><button class="btn btn-quiet danger" data-action="reset">Reset all progress</button></div>`,'Close'));
document.addEventListener('click',e=>{if(e.target.dataset.action==='reset'){state=blankState();save();document.querySelector('.modal-backdrop')?.remove();render();showToast('Progress reset.')}});
// User-added learning resources are restored from local storage on launch.
try{let saved=JSON.parse(localStorage.getItem(STORE)||'{}');if(saved.weekResources)Object.entries(saved.weekResources).forEach(([n,rs])=>roadmap[+n-1].resources=rs)}catch{}
const dashboardBase=renderDashboard;renderDashboard=function(){let html=dashboardBase();return html.replace(/MONDAY, NOVEMBER 16, 2026 · YOUR JOURNEY STARTS DECEMBER 7/,`${new Date().toLocaleDateString('en-US',{weekday:'long',month:'long',day:'numeric',year:'numeric'}).toUpperCase()} · YOUR JOURNEY STARTS DECEMBER 7`)};
const flowDiagrams=['CSV → parse → validate → summarize → JSON report','CSV → domain records → package modules → typed API → CLI','dataset → inspect → clean → compute → plot → interpret','GeoTIFF + boundary → inspect CRS → transform → clip → validate output','config → ingest → validate → transform → export → run manifest','HTTP request → validate → route → business logic → JSON response','API → SQLAlchemy session → PostgreSQL transaction → response','credential → password verify → token/session → authorization → resource','prompt → provider adapter → model inference → schema validation → comparison','user intent → tool proposal → policy/schema validation → function → result','documents → chunks → embeddings → vector search → cited answer','request → route → retrieval/tool → draft → evidence validation','workload → execution strategy → measurement → output check → decision','API job → queue → worker → durable status/result → client poll','source → tests/CI → image → deployment → health/rollback','authenticated upload → document record → worker extraction → AI summary → download','user flow → integrated services → test evidence → deployed release → technical defence'];
function weekPrerequisite(n){return n===1?'No formal programming prerequisite; be comfortable opening a terminal and editing a text file.':n<=5?'Use the Python, Git and file-handling skills from the preceding foundation week.':n<=8?'Use the prior week’s API/database work; keep its tested service boundary intact.':n<=12?'Use the backend and provider concepts from earlier weeks; do not assume model output is trusted.':'Use the API, database, testing and deployment foundations already built; reuse only what fits this week’s system.'}
function lessonStatus(n,i){return !!state.lessonCompletions[`${n}-${i}`]}
function exerciseStatus(n,i){return !!state.exerciseCompletions[`${n}-${i}`]}
function lessonMarkup(w,n,i){let l=w.lessons[i],book=state.bookmarks[`${n}-${i}`],done=lessonStatus(n,i),ex=w.extension;return `<div class="lesson-intro"><div class="lesson-meta"><span class="tag">LESSON ${String(i+1).padStart(2,'0')} / ${w.lessons.length}</span><span class="card-kicker">${l.minutes} MIN · ${done?'COMPLETED':'IN PROGRESS'}</span></div><h2>${esc(l.title)}</h2><p>${esc(l.why)}</p><div class="lesson-outcomes"><div><b>WHY IT MATTERS</b><span>${esc(l.objective.project)}</span></div><div><b>OUTCOME TO DEMONSTRATE</b><span>${esc(l.objective.evidence)}</span></div></div></div><details class="lesson-section" open><summary>Conceptual teaching</summary><div class="lesson-copy"><p>${esc(l.detail)}</p><p><b>Connect it to the system:</b> ${esc(l.objective.outcome)}</p><p><b>Engineering check:</b> What assumption does this concept require? What observable test would tell you that assumption has been violated?</p></div></details>${l.example?`<details class="lesson-section" open><summary>Worked example · ${esc(l.example.title)}</summary><div class="lesson-copy"><h4>Problem</h4><p>${esc(l.example.problem)}</p><h4>Reasoning</h4><p>${esc(l.example.reasoning)}</p><div class="code-toolbar"><span>RUNNABLE EXAMPLE</span><button class="btn btn-quiet" data-action="copy-code" data-code="${i}">Copy code</button></div><pre class="code-block"><code>${esc(l.example.code)}</code></pre><h4>Expected output</h4><pre class="output-block">${esc(l.example.output)}</pre><h4>Line-by-line focus</h4><p>${esc(l.example.explain)}</p><h4>Edge cases</h4><p>${esc(l.example.edges)}</p><h4>Common mistake</h4><p>${esc(l.example.mistake)}</p></div></details>`:`<details class="lesson-section"><summary>Worked reasoning · see the weekly example</summary><p class="lesson-copy">Use the week’s worked example to test this concept. Rewrite one line or assumption so it reflects <b>${esc(l.title)}</b>, then explain the changed behavior.</p></details>`}<details class="lesson-section"><summary>Guided practice for this lesson</summary><div class="lesson-copy"><p>Before marking complete, connect this lesson to its assigned guided exercise: <b>${esc(w.exercises[Math.min(3,Math.floor(i*4/w.lessons.length))])}</b></p><p>Write one testable claim, make the smallest implementation or diagram that supports it, and compare the result with the expected behavior.</p></div></details><div class="lesson-actions"><label class="inline-check"><input class="check" type="checkbox" data-lesson-complete="${n}-${i}" ${done?'checked':''}> Mark lesson complete</label><button class="btn ${book?'':'btn-quiet'}" data-action="lesson-bookmark" data-week="${n}" data-lesson="${i}">${book?'★ Bookmarked':'☆ Bookmark lesson'}</button></div><div class="lesson-reflection"><label for="lesson-note">Lesson notes</label><textarea id="lesson-note" data-lesson-note="${n}-${i}" placeholder="Record the mechanism you can now explain, evidence from your work, and what to revisit.">${esc(state.lessonNotes[`${n}-${i}`]||'')}</textarea><label for="lesson-question">Question to resolve</label><input id="lesson-question" data-lesson-question="${n}-${i}" value="${esc(state.lessonQuestions[`${n}-${i}`]||'')}" placeholder="What is still unclear?"><div class="lesson-actions"><button class="btn btn-quiet" data-action="lesson-to-journal" data-week="${n}" data-lesson="${i}">Add notes to journal</button><button class="btn btn-quiet" data-action="lesson-to-decision" data-week="${n}" data-lesson="${i}">Create decision record</button></div></div>`}
function assignmentMarkup(w,n){let a=w.extension.assignment,s=state.assignmentSubmissions[n]||{},hints=state.revealedHints[`assignment-${n}`]||0;return `<section class="assignment-panel"><div class="eyebrow">${esc(w.extension.category)} · WEEK ${n}</div><h2>${esc(a.title)}</h2><p class="assignment-statement">${esc(a.statement)}</p><div class="assignment-grid"><div><h3>Functional requirements</h3><ul>${a.requirements.map(x=>`<li>${esc(x)}</li>`).join('')}</ul><h3>Constraints & edge cases</h3><ul>${a.constraints.concat(a.edges).map(x=>`<li>${esc(x)}</li>`).join('')}</ul><h3>Input / expected output</h3><p>${esc(a.io)}</p></div><div><h3>Suggested architecture</h3><div class="flow-diagram">${flowDiagrams[n-1].split(' → ').map((x,i)=>`${i?'<i>→</i>':''}<span>${esc(x)}</span>`).join('')}</div><h3>Implementation milestones</h3><ol>${a.requirements.map((r,i)=>`<li>Milestone ${i+1}: ${esc(r)}</li>`).join('')}</ol><h3>Testing protocol</h3><p>Turn each stated edge case into a repeatable test. Verify the success path, boundary behavior and at least one failure path before marking the milestone complete.</p><h3>Git and documentation requirements</h3><ul><li>Commit a focused change after each milestone and keep generated data or secrets out of version control.</li><li>Include a README with clean setup, run, test and data instructions; provide a repository or artifact link when recording the submission.</li></ul><h3>Evaluation rubric</h3><ul>${a.rubric.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></div></div><details class="lesson-section"><summary>Progressive hints · reveal only when useful</summary>${a.hints.map((h,i)=>`<div class="hint-row"><span>HINT ${i+1}</span>${i<hints?esc(h):`<button class="text-link" data-action="reveal-hint" data-key="assignment-${n}">Reveal hint ${i+1}</button>`}</div>`).join('')}</details><h3>Submission checklist</h3><ul class="submission-list">${a.submission.map(x=>`<li>${esc(x)}</li>`).join('')}</ul><h3>Extension challenges</h3><ul>${a.extensions.map(x=>`<li>${esc(x)}</li>`).join('')}</ul><div class="submission-form"><h3>Record your assignment submission</h3><p>Save a repository, artifact or report link and a brief note. This record appears in the Project Tracker.</p><input id="submission-link" value="${esc(s.link||'')}" placeholder="Repository or artifact URL"><textarea id="submission-note" placeholder="What did you submit? What evidence should a reviewer inspect?">${esc(s.note||'')}</textarea><button class="btn btn-primary" data-action="record-submission" data-week="${n}">${s.submitted?'Update submission record':'Record submission'}</button>${s.submitted?`<span class="status complete">RECORDED ${fmt(s.date,{month:'short',day:'numeric'})}</span>`:''}</div></section>`}
function exerciseMarkup(w,n){let labels=['Basic understanding','Application','Problem solving','Engineering application'];return `<section class="learning-panel"><div class="eyebrow">GUIDED EXERCISES · INCREASING DIFFICULTY</div><h2>Build the skill in steps</h2><p class="page-sub">Attempt each task before opening its hints. Exercise checks contribute to lesson and weekly progress.</p>${w.exercises.map((x,i)=>{let h=state.revealedHints[`${n}-${i}`]||0;return `<article class="exercise-item"><div class="exercise-head"><span class="tag">${labels[i]}</span><label class="inline-check"><input type="checkbox" class="check" data-exercise-complete="${n}-${i}" ${exerciseStatus(n,i)?'checked':''}> Complete</label></div><h3>${esc(x)}</h3><p><b>Expected outcome:</b> produce a small artifact or test result that demonstrates this specific behavior and explain one failure case.</p><details><summary>Hints · ${h}/${w.extension.hints[i].length} revealed</summary>${w.extension.hints[i].map((hint,j)=>`<p class="hint-row">${j<h?esc(hint):`<button class="text-link" data-action="reveal-hint" data-key="${n}-${i}">Reveal hint ${j+1}</button>`}</p>`).join('')}</details></article>`}).join('')}</section>`}
function resourcesMarkup(w,n){let custom=(w.resources||[]).map((url,i)=>({title:url,url,focus:'Learner-added reference.',customIndex:i})),items=[...w.extension.resources,...custom];return `<section class="learning-panel"><div class="eyebrow">CURATED READING · OFFICIAL AND PRIMARY SOURCES</div><h2>Resources for this week</h2><p class="page-sub">Read with a question in mind. Focus notes identify the parts that support this week’s implementation.</p>${items.map(r=>`<article class="resource-item"><h3><a href="${esc(r.url)}" target="_blank" rel="noopener noreferrer">${esc(r.title)} ↗</a></h3><p>${esc(r.focus)}</p>${r.customIndex!==undefined?`<button class="text-link" data-action="remove-resource" data-week="${n}" data-index="${r.customIndex}">Remove added resource</button>`:''}</article>`).join('')}<div class="submission-form"><h3>Add a personal reference</h3><input class="row-input" id="resource-link" placeholder="Paste a documentation or article URL"><button class="btn btn-quiet" data-action="add-resource" data-week="${n}">Add resource</button></div></section>`}
function overviewMarkup(w,n){return `<section class="learning-panel"><div class="eyebrow">WEEK ${n} · ${esc(w.extension.category)}</div><h2>What you will learn and produce</h2><p class="page-sub">${esc(w.overview)}</p><div class="overview-objectives">${w.objectives.map((o,i)=>`<article class="objective-card"><div class="objective-title"><span class="topic-bullet">0${i+1}</span>${esc(o.title)}</div><div class="objective-detail"><b>Understand and implement</b>${esc(o.outcome)}</div><div class="objective-detail"><b>Evidence to demonstrate</b>${esc(o.evidence)}</div><div class="objective-detail"><b>Connection to this week’s work</b>${esc(o.project)}</div></article>`).join('')}</div><h3>Topic sequence</h3>${w.topics.map((t,i)=>`<article class="topic-group"><div class="topic-group-title">${String(i+1).padStart(2,'0')} · ${esc(t.title)}</div><p>${esc(t.detail)}</p></article>`).join('')}<article class="week-deliverable"><b>WEEKLY OUTCOME</b>${esc(w.deliverable)}</article></section>`}
function assessmentMarkup(w,n){let result=state.assessments[n],answers=state.quizAnswers[n]||{};return `<section class="learning-panel"><div class="eyebrow">KNOWLEDGE CHECK · APPLY AND EXPLAIN</div><h2>Check your understanding</h2><p class="page-sub">Some questions trace code or diagnose behavior. Submit to see explanations, then self-check the short response against the rubric.</p>${w.extension.quiz.map((q,i)=>`<fieldset class="quiz-question"><legend><span class="tag">${esc(q.type.toUpperCase())}</span> ${esc(q.question)}</legend>${q.options.map((option,j)=>`<label class="quiz-option"><input type="radio" name="quiz-${n}-${i}" value="${j}" ${answers[i]===j?'checked':''}> ${esc(option)}</label>`).join('')}${result?.completed?`<p class="quiz-explanation ${result.answers[i]===q.answer?'correct':'incorrect'}"><b>${result.answers[i]===q.answer?'Correct':'Review this'}.</b> ${esc(q.explanation)}</p>`:''}</fieldset>`).join('')}<div class="quiz-question"><h3>Short answer · explain your evidence</h3><p>In your own words, explain how you would demonstrate this outcome: <b>${esc(w.objectives[0].outcome)}</b></p><textarea id="short-answer" placeholder="Write 2–4 sentences and name evidence from your work.">${esc(answers.short||'')}</textarea>${result?.completed?`<p class="quiz-explanation">Compare with this evidence criterion: ${esc(w.objectives[0].evidence)}</p><label class="inline-check"><input type="checkbox" id="short-self-check" ${result.shortSelfCheck?'checked':''}> My answer names both the implementation and evidence</label>`:''}</div><button class="btn btn-primary" data-action="submit-quiz" data-week="${n}">${result?.completed?'Update assessment':'Submit knowledge check'}</button>${result?.completed?`<div class="assessment-result"><b>Recorded score: ${result.score}/${result.total}</b><span>${fmt(result.date,{month:'short',day:'numeric',year:'numeric'})} · results feed into Analytics</span></div>`:''}</section>`}
function renderLearningWeek(n){let w=roadmap[n-1];if(!w)return '<div class="empty">Week not found.</div>';let tab=state.weekTabs[n]||'overview',active=Math.max(0,Math.min(w.lessons.length-1,Number(state.activeLessons[n]||0))),completed=w.lessons.filter((_,i)=>lessonStatus(n,i)).length,assign=state.assignmentSubmissions[n]?.submitted;let tabs=[['overview','Overview'],['lessons','Lessons'],['exercises','Guided exercises'],['assignment','Assignment'],['assessment','Knowledge check'],['resources','Resources'],['schedule','Daily schedule']];return `<button class="detail-back" onclick="location.hash='#roadmap'">← BACK TO ROADMAP</button><div class="hero-row"><div><div class="eyebrow">PHASE ${w.phase+1} · ${phaseLabel(w.phase).toUpperCase()} · WEEK ${n} · ${range(w)}</div><h1 class="page-title">${esc(w.title)}</h1><p class="page-sub">${esc(w.overview)}</p></div><span class="tag">${weekPercent(n)}% COMPLETE</span></div><div class="progress-track"><span style="width:${weekPercent(n)}%"></span></div><nav class="curriculum-tabs">${tabs.map(([key,label])=>`<button class="curriculum-tab ${tab===key?'active':''}" data-action="week-tab" data-week="${n}" data-tab="${key}">${label}${key==='lessons'?` <small>${completed}/${w.lessons.length}</small>`:''}</button>`).join('')}</nav>${tab==='overview'?overviewMarkup(w,n):tab==='lessons'?`<div class="learning-layout"><aside class="lesson-sidebar"><div class="card-kicker">LESSON SEQUENCE</div>${w.lessons.map((l,i)=>`<button class="lesson-nav-item ${i===active?'active':''}" data-action="select-lesson" data-week="${n}" data-lesson="${i}"><span class="lesson-nav-status ${lessonStatus(n,i)?'done':''}">${lessonStatus(n,i)?'✓':String(i+1).padStart(2,'0')}</span><span>${esc(l.title)}</span>${state.bookmarks[`${n}-${i}`]?'★':''}</button>`).join('')}</aside><main class="lesson-reading">${lessonMarkup(w,n,active)}<div class="lesson-pager"><button class="btn btn-quiet" data-action="select-lesson" data-week="${n}" data-lesson="${Math.max(0,active-1)}" ${active===0?'disabled':''}>← Previous lesson</button><button class="btn btn-primary" data-action="select-lesson" data-week="${n}" data-lesson="${Math.min(w.lessons.length-1,active+1)}" ${active===w.lessons.length-1?'disabled':''}>Next lesson →</button></div></main><aside class="learning-context"><article class="card"><div class="card-kicker">WEEK PROGRESS</div><div class="metric">${weekPercent(n)}<span class="metric-suffix">%</span></div><div class="progress-track"><span style="width:${weekPercent(n)}%"></span></div><p class="metric-caption">${completed}/${w.lessons.length} lessons · ${w.exercises.filter((_,i)=>exerciseStatus(n,i)).length}/${w.exercises.length} exercises · ${assign?'assignment recorded':'assignment open'}</p></article><article class="card"><div class="card-kicker">PREREQUISITES</div><p>${esc(weekPrerequisite(n))}</p><div class="card-kicker">WEEKLY OUTCOME</div><p>${esc(w.extension.assignment.statement)}</p><label class="inline-check"><input type="checkbox" class="check" data-deliverable="${n}" ${state.deliverables[n]?'checked':''}> Mark weekly deliverable complete</label></article><article class="card"><div class="card-kicker">READING PROGRESS</div><p>${completed} lessons explicitly completed. Bookmarked lessons stay at the top of your review list.</p><button class="text-link" data-action="week-tab" data-week="${n}" data-tab="assessment">GO TO KNOWLEDGE CHECK →</button></article></aside></div>`:tab==='exercises'?exerciseMarkup(w,n):tab==='assignment'?assignmentMarkup(w,n):tab==='assessment'?assessmentMarkup(w,n):tab==='resources'?resourcesMarkup(w,n):`<section class="learning-panel"><div class="eyebrow">A SPECIFIC PLAN FOR THIS MODULE · EST. ${w.days.reduce((a,d)=>a+d.hours,0)} HOURS</div><h2>Daily learning schedule</h2><p class="page-sub">Each day’s target matches the original roadmap allocation. The activities are derived from this week’s lessons, guided exercises and assignment.</p>${w.days.map((d,i)=>`<article class="schedule-item"><label class="inline-check"><input type="checkbox" class="check" data-task="${taskKey(n,i)}" ${state.tasks[taskKey(n,i)]?'checked':''}><span>Day ${i+1} · ${d.hours}h</span></label><div><h3>${esc(d.title)}</h3><p>${esc(d.description)}</p></div></article>`).join('')}</section>`}`}
renderWeek=renderLearningWeek;
const oldDashboard=renderDashboard;renderDashboard=function(){let html=oldDashboard(),w=currentWeek(),list=`<ul class="week-objectives">${w.objectives.slice(0,2).map(o=>`<li><b>${esc(o.title)}</b>: ${esc(o.outcome)}</li>`).join('')}</ul>`;return html.replace(/<ul class="week-objectives">[\s\S]*?<\/ul>/,list)};
weekCard=function(w){return `<a class="week-card" href="#week-${w.n}" data-week-search="${esc((w.title+' '+w.topics.map(t=>t.title).join(' ')).toLowerCase())}"><span class="week-index">${String(w.n).padStart(2,'0')}</span><span><h3>${esc(w.title)}</h3><p>${range(w)} · ${esc(w.deliverable.split('.')[0]+'.')}</p></span><span class="week-card-right"><small>${completedWeekUnits(w.n)}/${weekUnits(w.n)} UNITS</small><span class="mini-progress"><span style="width:${weekPercent(w.n)}%"></span></span></span></a>`};
const renderProjectsBase=renderProjects;renderProjects=function(){let html=renderProjectsBase();return html+`<div class="section-heading"><h2>Curriculum assignment submissions</h2><span class="card-kicker">LINKED TO WEEKLY ASSIGNMENTS</span></div><article class="card">${roadmap.map(w=>{let s=state.assignmentSubmissions[w.n];return `<div class="submission-row"><span class="week-index">W${w.n}</span><span><b>${esc(w.extension.assignment.title)}</b><small>${s?.submitted?`Submitted ${fmt(s.date,{month:'short',day:'numeric'})}`:'Not submitted'}</small></span>${s?.link?`<a class="text-link" href="${esc(s.link)}" target="_blank" rel="noreferrer">OPEN ARTIFACT ↗</a>`:`<a class="text-link" href="#week-${w.n}">OPEN ASSIGNMENT →</a>`}</div>`}).join('')}</article>`};
const renderAnalyticsBase=renderAnalytics;renderAnalytics=function(){let html=renderAnalyticsBase(),scores=roadmap.filter(w=>state.assessments[w.n]?.completed);let content=`<div class="section-heading"><h2>Knowledge checks</h2><span class="card-kicker">${scores.length}/17 SUBMITTED</span></div><article class="card">${scores.length?scores.map(w=>`<div class="assessment-row"><span>Week ${w.n} · ${esc(w.title)}</span><b>${state.assessments[w.n].score}/${state.assessments[w.n].total}</b><small>${fmt(state.assessments[w.n].date,{month:'short',day:'numeric'})}</small></div>`).join(''):'<div class="empty">Assessment scores appear after you submit a weekly knowledge check.</div>'}</article>`;return html+content};
document.addEventListener('click',async e=>{let a=e.target.closest('[data-action]');if(!a)return;let act=a.dataset.action,n=+a.dataset.week,i=+a.dataset.lesson;if(act==='week-tab'){state.weekTabs[n]=a.dataset.tab;save();render()}if(act==='select-lesson'){state.activeLessons[n]=i;state.weekTabs[n]='lessons';save();render()}if(act==='lesson-bookmark'){let k=`${n}-${i}`;state.bookmarks[k]=!state.bookmarks[k];save();render()}if(act==='reveal-hint'){let k=a.dataset.key;state.revealedHints[k]=(state.revealedHints[k]||0)+1;save();render()}if(act==='record-submission'){let link=document.querySelector('#submission-link').value.trim(),note=document.querySelector('#submission-note').value.trim();state.assignmentSubmissions[n]={submitted:true,link,note,date:todayISO()};save();render();showToast('Assignment submission recorded in Project Tracker.')}if(act==='submit-quiz'){let w=roadmap[n-1],answers={short:document.querySelector('#short-answer')?.value.trim()||''},score=0,total=w.extension.quiz.length+1;w.extension.quiz.forEach((q,j)=>{let selected=document.querySelector(`input[name="quiz-${n}-${j}"]:checked`);let val=selected?Number(selected.value):null;answers[j]=val;if(val===q.answer)score++});let shortSelfCheck=document.querySelector('#short-self-check')?.checked||false;if(answers.short&&shortSelfCheck)score++;state.quizAnswers[n]=answers;state.assessments[n]={completed:true,answers,score,total,date:todayISO(),shortSelfCheck};save();render()}if(act==='lesson-to-journal'){let key=`${n}-${i}`,note=state.lessonNotes[key]||'',question=state.lessonQuestions[key]||'';if(!note&&!question){showToast('Add lesson notes or a question first.');return}state.journals.push({id:crypto.randomUUID(),date:todayISO(),learned:`Week ${n}, ${roadmap[n-1].lessons[i].title}: ${note}`,built:'',problems:'',ai:'',decisions:'',revisit:question});save();showToast('Lesson reflection added to Engineering Journal.')}if(act==='lesson-to-decision'){location.hash='#decisions';showToast('Use “Record a decision” to capture this lesson’s design question.')}if(act==='copy-code'){let code=roadmap[n-1]?.lessons[i]?.example?.code;if(code)try{await navigator.clipboard.writeText(code);showToast('Code copied.')}catch{showToast('Clipboard access is unavailable here. Select the code block to copy it.')}}});
document.addEventListener('change',e=>{let t=e.target;if(t.matches('[data-lesson-complete]')){state.lessonCompletions[t.dataset.lessonComplete]=t.checked;save();render()}if(t.matches('[data-exercise-complete]')){state.exerciseCompletions[t.dataset.exerciseComplete]=t.checked;save();render()}if(t.matches('[data-lesson-note]')){state.lessonNotes[t.dataset.lessonNote]=t.value;save()}if(t.matches('[data-lesson-question]')){state.lessonQuestions[t.dataset.lessonQuestion]=t.value;save()}});
document.addEventListener('input',e=>{let t=e.target;if(t.matches('[data-lesson-note]')){let k=t.dataset.lessonNote;state.lessonNotes[k]=t.value;save()}if(t.matches('[data-lesson-question]')){let k=t.dataset.lessonQuestion;state.lessonQuestions[k]=t.value;save()}});
document.addEventListener('click',e=>{let a=e.target.closest('[data-action="lesson-to-decision"]');if(!a)return;let n=+a.dataset.week,i=+a.dataset.lesson,key=`${n}-${i}`,question=state.lessonQuestions[key]?.trim(),lesson=roadmap[n-1].lessons[i];state.decisions.push({id:crypto.randomUUID(),date:todayISO(),title:question||`Engineering question: ${lesson.title}`,problem:`Week ${n} · ${lesson.title}. ${question||'Record the design choice, evidence and trade-offs raised while studying this lesson.'}`,requirements:'State the relevant functional, reliability, performance or data-quality requirement.',alternatives:'List at least two plausible approaches.',selected:'Record the selected approach after comparing alternatives.',reasoning:'Explain the mechanism and evidence behind the selection.',tradeoffs:'Record costs, limitations and assumptions.',validation:'Define a test or observation that would validate the decision.',future:'State what new evidence would change this decision.'});save();showToast('A draft technical decision has been added to the Decision Log.')});
render();
